/**
 * @description
 *
 * @param  {Matrix} matrix
 * @param  {number} scale_x
 * @param  {number} scale_y
 * @param  {number} rotation
 * @param  {number} [tx=0]
 * @param  {number} [ty=0]
 * @return {void}
 * @method
 * @public
 */
export const execute = (matrix, scale_x, scale_y, rotation = 0, tx = 0, ty = 0) => {
    matrix.identity();
    matrix.rotate(rotation);
    matrix.scale(scale_x, scale_y);
    matrix.translate(tx, ty);
};
